def parse_args(text, idx):
    # extract balanced-paren substring after match
    i = idx
    while text[i] != '(':
        i += 1
    depth = 0; j = i
    while j < len(text):
        if text[j] == '(': depth += 1
        elif text[j] == ')':
            depth -= 1
            if depth == 0: break
        j += 1
    inner = text[i+1:j]
    # split top-level commas
    parts, d, cur = [], 0, ''
    for ch in inner:
        if ch in '([': d += 1
        elif ch in ')]': d -= 1
        elif ch == ',' and d == 0:
            parts.append(cur.strip()); cur = ''
            continue
        cur += ch
    parts.append(cur.strip())
    return parts
